<?php
require_once "db.php";
require_once "auth.php";
require_once "role_check.php";
require_role(['Administrator']);
$message = ''; $error = '';
function esc($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  try {
    if (isset($_POST['add_ingredient'])) {
      $name = trim($_POST['ingredient_name'] ?? ''); $unit = trim($_POST['unit'] ?? '');
      $qty = filter_var($_POST['quantity_in_stock'] ?? null, FILTER_VALIDATE_FLOAT); $low = filter_var($_POST['low_stock_level'] ?? null, FILTER_VALIDATE_FLOAT);
      if ($name === '' || $unit === '' || $qty === false || $low === false || $qty < 0 || $low < 0) throw new RuntimeException('Enter a name, unit, and valid non-negative quantities.');
      $st = $conn->prepare('INSERT INTO ingredients (ingredient_name, unit, quantity_in_stock, low_stock_level) VALUES (?, ?, ?, ?)'); $st->bind_param('ssdd', $name, $unit, $qty, $low); $st->execute(); $st->close(); $message = 'Ingredient added.';
    } elseif (isset($_POST['stock_in'])) {
      $id = (int)($_POST['ingredient_id'] ?? 0); $qty = filter_var($_POST['quantity'] ?? null, FILTER_VALIDATE_FLOAT); $remarks = trim($_POST['remarks'] ?? 'Stock received');
      if ($id < 1 || $qty === false || $qty <= 0) throw new RuntimeException('Enter a valid ingredient and quantity.');
      $conn->begin_transaction(); $st = $conn->prepare('UPDATE ingredients SET quantity_in_stock = quantity_in_stock + ? WHERE id = ?'); $st->bind_param('di', $qty, $id); $st->execute(); if (!$st->affected_rows) throw new RuntimeException('Ingredient not found.'); $st->close();
      $mv = $conn->prepare("INSERT INTO ingredient_movements (ingredient_id, movement_type, quantity, remarks) VALUES (?, 'Stock In', ?, ?)"); $mv->bind_param('ids', $id, $qty, $remarks); $mv->execute(); $mv->close(); $conn->commit(); $message = 'Ingredient stock updated.';
    } elseif (isset($_POST['save_recipe'])) {
      $productId = (int)($_POST['product_id'] ?? 0); $ingredientId = (int)($_POST['ingredient_id'] ?? 0); $qty = filter_var($_POST['quantity_required'] ?? null, FILTER_VALIDATE_FLOAT);
      if ($productId < 1 || $ingredientId < 1 || $qty === false || $qty <= 0) throw new RuntimeException('Choose a menu item and ingredient, then enter the measured amount used per one menu item.');
      $st = $conn->prepare('INSERT INTO product_recipes (product_id, ingredient_id, quantity_required) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE quantity_required = VALUES(quantity_required)'); $st->bind_param('iid', $productId, $ingredientId, $qty); $st->execute(); $st->close(); $message = 'Recipe ingredient saved. Quantity is per one menu item.';
    } elseif (isset($_POST['delete_recipe'])) {
      $id = (int)($_POST['recipe_id'] ?? 0); $st = $conn->prepare('DELETE FROM product_recipes WHERE id = ?'); $st->bind_param('i', $id); $st->execute(); $st->close(); $message = 'Recipe mapping removed.';
    }
  } catch (Throwable $e) { if ($conn->errno || $conn->sqlstate !== '00000') { try { $conn->rollback(); } catch (Throwable $ignored) {} } $error = $e instanceof RuntimeException ? $e->getMessage() : 'Unable to save this change. Check for duplicate ingredient names and confirm the migration has been run.'; }
}
$ingredients = $conn->query('SELECT * FROM ingredients ORDER BY ingredient_name');
$ingredientOptions = []; while ($r = $ingredients->fetch_assoc()) $ingredientOptions[] = $r;
$products = $conn->query('SELECT id, product_name FROM products ORDER BY product_name'); $productOptions=[]; while ($r=$products->fetch_assoc()) $productOptions[]=$r;
$recipes = $conn->query('SELECT pr.id, p.product_name, i.ingredient_name, i.unit, pr.quantity_required FROM product_recipes pr JOIN products p ON p.id=pr.product_id JOIN ingredients i ON i.id=pr.ingredient_id ORDER BY p.product_name, i.ingredient_name');
$movements = $conn->query('SELECT m.*, i.ingredient_name, i.unit FROM ingredient_movements m JOIN ingredients i ON i.id=m.ingredient_id ORDER BY m.id DESC LIMIT 30');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ingredients & Recipes - AR Homemade</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="style.css"><style>
