</style><style>body{background:#f8f7f5}.wrap{max-width:1200px;margin:30px auto;padding:0 16px}.panel{background:white;border:1px solid #e7e0dc;border-radius:14px;padding:20px;margin-bottom:20px}.table-responsive{max-height:420px}</style></head><body><div class="topbar"><div class="navbar-inner"><a href="index.php" class="logo"><img src="images/ar_logo.png" alt="AR Homemade"></a><div class="nav-links"><a href="index.php">Dashboard</a><a href="orders.php">Orders</a><a href="products.php">Menu Items</a><a href="inventory.php" class="active">Ingredients & Recipes</a><a href="reports.php">Reports</a><a href="users.php">Users</a><a href="logout.php">Logout</a></div></div></div><main class="wrap"><h1 class="h3 mb-1">Ingredient Inventory & Recipes</h1><p class="text-muted">Track raw ingredients only. Menu items remain in the order catalog. Set recipe quantities using actual measured amounts; no recipes are prefilled.</p>
<?php if($message): ?><div class="alert alert-success"><?=esc($message)?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?=esc($error)?></div><?php endif; ?>
<div class="row g-3"><div class="col-lg-6"><section class="panel"><h2 class="h5">Add Ingredient</h2><form method="post" class="row g-2"><div class="col-md-6"><label class="form-label">Ingredient name</label><input name="ingredient_name" class="form-control" required placeholder="e.g. Burger patty"></div><div class="col-md-6"><label class="form-label">Unit</label><input name="unit" class="form-control" required placeholder="pcs, kg, g, L"></div><div class="col-md-6"><label class="form-label">Opening stock</label><input type="number" min="0" step="0.001" name="quantity_in_stock" class="form-control" required value="0"></div><div class="col-md-6"><label class="form-label">Low-stock level</label><input type="number" min="0" step="0.001" name="low_stock_level" class="form-control" required value="0"></div><div class="col-12"><button name="add_ingredient" class="btn btn-danger">Add Ingredient</button></div></form></section></div><div class="col-lg-6"><section class="panel"><h2 class="h5">Record Stock Received</h2><form method="post" class="row g-2"><div class="col-12"><label class="form-label">Ingredient</label><select name="ingredient_id" class="form-select" required><option value="">Choose ingredient</option><?php foreach($ingredientOptions as $i):?><option value="<?=$i['id']?>"><?=esc($i['ingredient_name'])?> (<?=esc($i['unit'])?>)</option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Quantity received</label><input name="quantity" type="number" min="0.001" step="0.001" class="form-control" required></div><div class="col-md-6"><label class="form-label">Remarks</label><input name="remarks" class="form-control" placeholder="Supplier / delivery"></div><div class="col-12"><button name="stock_in" class="btn btn-outline-danger">Add to Stock</button></div></form></section></div></div>
<section class="panel"><h2 class="h5">Ingredient Stock</h2><div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>Ingredient</th><th>On hand</th><th>Unit</th><th>Low-stock level</th><th>Status</th></tr></thead><tbody><?php foreach($ingredientOptions as $i):?><tr><td><?=esc($i['ingredient_name'])?></td><td><?=number_format((float)$i['quantity_in_stock'],3)?></td><td><?=esc($i['unit'])?></td><td><?=number_format((float)$i['low_stock_level'],3)?></td><td><?php if((float)$i['quantity_in_stock'] <= (float)$i['low_stock_level']):?><span class="badge text-bg-warning">Low stock</span><?php else:?><span class="badge text-bg-success">Available</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$ingredientOptions):?><tr><td colspan="5" class="text-muted">No ingredients yet. Add actual ingredients above.</td></tr><?php endif;?></tbody></table></div></section>
<div class="row g-3"><div class="col-lg-5"><section class="panel"><h2 class="h5">Map a Recipe Ingredient</h2><p class="small text-muted">Quantity means the amount of this ingredient used to make one menu item. Add every ingredient required by the recipe.</p><form method="post" class="vstack gap-2"><label class="form-label">Menu item</label><select name="product_id" class="form-select" required><option value="">Choose menu item</option><?php foreach($productOptions as $p):?><option value="<?=$p['id']?>"><?=esc($p['product_name'])?></option><?php endforeach;?></select><label class="form-label">Ingredient</label><select name="ingredient_id" class="form-select" required><option value="">Choose ingredient</option><?php foreach($ingredientOptions as $i):?><option value="<?=$i['id']?>"><?=esc($i['ingredient_name'])?> (<?=esc($i['unit'])?>)</option><?php endforeach;?></select><label class="form-label">Quantity used per menu item</label><input type="number" name="quantity_required" min="0.001" step="0.001" class="form-control" required><button name="save_recipe" class="btn btn-danger">Save Recipe Mapping</button></form></section></div><div class="col-lg-7"><section class="panel"><h2 class="h5">Configured Recipes</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Menu item</th><th>Ingredient</th><th>Qty / item</th><th></th></tr></thead><tbody><?php while($r=$recipes->fetch_assoc()):?><tr><td><?=esc($r['product_name'])?></td><td><?=esc($r['ingredient_name'])?></td><td><?=number_format((float)$r['quantity_required'],3)?> <?=esc($r['unit'])?></td><td><form method="post" onsubmit="return confirm('Remove this recipe mapping?')"><input type="hidden" name="recipe_id" value="<?=$r['id']?>"><button name="delete_recipe" class="btn btn-sm btn-outline-danger">Remove</button></form></td></tr><?php endwhile;?></tbody></table></div></section></div></div>
<section class="panel"><h2 class="h5">Recent Ingredient Movements</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Date</th><th>Ingredient</th><th>Movement</th><th>Quantity</th><th>Remarks</th></tr></thead><tbody><?php while($m=$movements->fetch_assoc()):?><tr><td><?=esc($m['movement_date'])?></td><td><?=esc($m['ingredient_name'])?></td><td><?=esc($m['movement_type'])?></td><td><?=number_format((float)$m['quantity'],3)?> <?=esc($m['unit'])?></td><td><?=esc($m['remarks'])?></td></tr><?php endwhile;?></tbody></table></div></section></main></body></html>
